INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ANGLO_SAXON','Anglo-Saxon period',400,1000)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_POLLINGTON_ELDER_GODS','secondary scholarship','Stephen Pollington, The Elder Gods: The Otherworld of Early England (2011)','Anglo-Saxon paganism, deities, cosmology and ritual'),
 ('SRC_BEDE_DTR','primary text','Bede, De temporum ratione (The Reckoning of Time), c. 725 CE','Old English month-names; sole attestation of Eostre and Hreda')
INSERT INTO _e VALUES
 ('ENT_ASX_PANTHEON','Anglo-Saxon Pantheon','collective','collective','Anglo-Saxon','pantheon','B','Hub collective for the pre-Christian Old English gods reconstructed from royal genealogies, place-names, charms, Bede and Norse cognates.'),
 ('ENT_ASX_WODEN','Woden','deity','sky/sovereign deity','Anglo-Saxon','war, wisdom, kingship, the dead','B','Chief god; head of most Anglo-Saxon royal genealogies (West Saxon, Mercian lines) and named in the Nine Herbs Charm. Old English cognate of Norse Odin.'),
 ('ENT_ASX_THUNOR','Thunor','deity','thunder deity','Anglo-Saxon','thunder, sky, protection','B','Thunder-god attested in place-names (Thunderfield, Thundersley) and the weekday Thunresdaeg. Old English cognate of Norse Thor.'),
 ('ENT_ASX_TIW','Tiw','deity','war/sky deity','Anglo-Saxon','war, law, the sky','B','War-god attested in place-names (Tysoe, Tuesley) and the weekday Tiwesdaeg. Old English cognate of Norse Tyr.'),
 ('ENT_ASX_FRIGE','Frige','deity','mother/sovereign goddess','Anglo-Saxon','marriage, household, fertility','B','Goddess attested in the weekday Frigedaeg (Friday). Old English cognate of Norse Frigg.'),
 ('ENT_ASX_EOSTRE','Eostre','deity','dawn/spring goddess','Anglo-Saxon','dawn, spring, renewal','C','Dawn/spring goddess named by Bede as eponym of the month Eosturmonath, from which English Easter derives; sole near-contemporary attestation.'),
 ('ENT_ASX_HREDA','Hreda','deity','goddess','Anglo-Saxon','victory, glory, the early-spring month','C','Goddess named by Bede as eponym of the month Hredmonath (roughly March); known only from that passage.'),
 ('ENT_ASX_SEAXNEAT','Seaxneat','deity','ancestral/tribal deity','Anglo-Saxon','kingship, tribal ancestry','C','Divine ancestor heading the East Saxon royal genealogy; cognate of Continental Saxon Saxnot in the Old Saxon Baptismal Vow.'),
 ('ENT_ASX_ING','Ing','deity','fertility deity','Anglo-Saxon','fertility, peace, ancestry','C','Ing/Ingui, eponym of the Ingaevones, named in the Old English Rune Poem; cognate of Norse Freyr (Yngvi-Freyr).'),
 ('ENT_ASX_WULDOR','Wuldor','deity','deity','Anglo-Saxon','glory, splendour','C','Glory-god inferred from the noun wuldor and place-names; Old English cognate of Norse Ullr.'),
 ('ENT_ASX_ERCE','Erce','deity','earth-mother goddess','Anglo-Saxon','earth, fertility of the fields','C','Earth-mother addressed as ''Erce, eorthan modor'' in the Old English Aecerbot (field-remedy) charm.');
